<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';

$user = require_auth();
$pdo = db();
$error = null;
$success = null;
function h(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
function role_label(string $r): string { return ['admin'=>'مدیر','teacher'=>'مدرس','student'=>'دانش‌آموز'][$r] ?? $r; }
function dt(?string $v): string { if (!$v) return '—'; $t=strtotime($v); return $t ? date('Y/m/d H:i',$t) : $v; }
function manager(array $u): bool { return in_array($u['role'], ['teacher','admin'], true); }
function admin_only(array $u): bool { return $u['role'] === 'admin'; }
function url_page(string $p): string { return '/panel/?page='.rawurlencode($p); }

$hasStarts=(bool)$pdo->query("SHOW COLUMNS FROM classes LIKE 'starts_at'")->fetch();
$hasGuest=(bool)$pdo->query("SHOW COLUMNS FROM classes LIKE 'allow_guest'")->fetch();
$hasAllowed=(bool)$pdo->query("SHOW TABLES LIKE 'class_allowed_users'")->fetch();
$page=(string)($_GET['page'] ?? 'dashboard');
$pages=['dashboard','create_student','students','classes','create_class','create_access','admins','ads'];
if(!in_array($page,$pages,true)) $page='dashboard';
if(!manager($user) && $page!=='dashboard') $page='dashboard';
if(!admin_only($user) && $page==='admins') $page='dashboard';

if($_SERVER['REQUEST_METHOD']==='POST') {
 try {
  verify_csrf();
  $action=(string)($_POST['action'] ?? '');
  if($action==='create_student') {
   require_teacher(); $name=trim((string)($_POST['name']??'')); $email=strtolower(trim((string)($_POST['email']??''))); $pass=(string)($_POST['password']??'');
   if(mb_strlen($name)<2||mb_strlen($name)>100) throw new InvalidArgumentException('نام دانش‌آموز معتبر نیست.');
   if(!filter_var($email,FILTER_VALIDATE_EMAIL)) throw new InvalidArgumentException('ایمیل معتبر نیست.');
   if(strlen($pass)<8) throw new InvalidArgumentException('رمز عبور باید حداقل ۸ کاراکتر باشد.');
   $q=$pdo->prepare('SELECT id FROM users WHERE email=?'); $q->execute([$email]); if($q->fetch()) throw new InvalidArgumentException('این ایمیل قبلاً ثبت شده است.');
   $pdo->prepare("INSERT INTO users(name,email,password,role,created_at,updated_at) VALUES(?,?,?,'student',NOW(),NOW())")->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]); $success='دانش‌آموز ساخته شد.'; $page='students';
  }
  if($action==='create_class') {
   require_teacher(); $title=trim((string)($_POST['title']??'')); $desc=trim((string)($_POST['description']??'')); $starts=trim((string)($_POST['starts_at']??'')); $duration=max(15,min(1440,(int)($_POST['duration']??60))); $guest=$hasGuest&&!empty($_POST['allow_guest'])?1:0;
   if($title===''||mb_strlen($title)>200) throw new InvalidArgumentException('عنوان کلاس را وارد کنید.');
   $ts=$hasStarts?strtotime($starts):time(); if(!$ts||$ts<time()-60) throw new InvalidArgumentException('زمان کلاس را درست وارد کنید.');
   do{$code=strtoupper(bin2hex(random_bytes(4)));$q=$pdo->prepare('SELECT id FROM classes WHERE room_code=?');$q->execute([$code]);}while($q->fetch());
   $start=date('Y-m-d H:i:s',$ts); $exp=date('Y-m-d H:i:s',$ts+$duration*60);
   if($hasStarts&&$hasGuest){$q=$pdo->prepare("INSERT INTO classes(teacher_id,title,description,room_code,status,allow_guest,starts_at,expires_at) VALUES(?,?,?,?, 'scheduled',?,?,?)");$q->execute([$user['id'],$title,$desc?:null,$code,$guest,$start,$exp]);}
   elseif($hasStarts){$q=$pdo->prepare("INSERT INTO classes(teacher_id,title,description,room_code,status,starts_at,expires_at) VALUES(?,?,?,?, 'scheduled',?,?)");$q->execute([$user['id'],$title,$desc?:null,$code,$start,$exp]);}
   elseif($hasGuest){$q=$pdo->prepare("INSERT INTO classes(teacher_id,title,description,room_code,status,allow_guest,expires_at) VALUES(?,?,?,?, 'scheduled',?,?)");$q->execute([$user['id'],$title,$desc?:null,$code,$guest,$exp]);}
   else{$q=$pdo->prepare("INSERT INTO classes(teacher_id,title,description,room_code,status,expires_at) VALUES(?,?,?,?, 'scheduled',?)");$q->execute([$user['id'],$title,$desc?:null,$code,$exp]);}
   $success='کلاس ساخته شد.'; $page='classes';
  }
  if($action==='edit_class') {
   require_teacher(); $id=(int)($_POST['class_id']??0); $title=trim((string)($_POST['title']??'')); $desc=trim((string)($_POST['description']??'')); $starts=trim((string)($_POST['starts_at']??'')); $expires=trim((string)($_POST['expires_at']??'')); $guest=$hasGuest&&!empty($_POST['allow_guest'])?1:0;
   if($id<1||$title==='') throw new InvalidArgumentException('اطلاعات کلاس معتبر نیست.');
   $owner=$user['role']==='admin'?'id=?':'id=? AND teacher_id=?'; $set='title=?,description=?'; $params=[$title,$desc?:null];
   if($hasStarts&&$starts!==''){$x=strtotime($starts);if(!$x)throw new InvalidArgumentException('زمان شروع معتبر نیست.');$set.=',starts_at=?';$params[]=date('Y-m-d H:i:s',$x);}
   if($expires!==''){$x=strtotime($expires);if(!$x)throw new InvalidArgumentException('زمان پایان معتبر نیست.');$set.=',expires_at=?';$params[]=date('Y-m-d H:i:s',$x);}
   if($hasGuest){$set.=',allow_guest=?';$params[]=$guest;} $params[]=$id; if($user['role']!=='admin')$params[]=$user['id'];
   $pdo->prepare("UPDATE classes SET $set,updated_at=NOW() WHERE $owner")->execute($params); $success='کلاس ویرایش شد.'; $page='classes';
  }
  if($action==='delete_class') {
   require_teacher(); $id=(int)($_POST['class_id']??0); $q=$user['role']==='admin'?$pdo->prepare('DELETE FROM classes WHERE id=?'):$pdo->prepare('DELETE FROM classes WHERE id=? AND teacher_id=?'); $user['role']==='admin'?$q->execute([$id]):$q->execute([$id,$user['id']]); $success='کلاس حذف شد.'; $page='classes';
  }
  if($action==='create_access') {
   require_teacher(); if(!$hasAllowed) throw new RuntimeException('جدول کاربران مجاز ساخته نشده است.');
   $cid=(int)($_POST['class_id']??0); $uid=(int)($_POST['user_id']??0); if($cid<1||$uid<1) throw new InvalidArgumentException('کاربر و کلاس را انتخاب کنید.');
   $q=$user['role']==='admin'?$pdo->prepare('SELECT id,title FROM classes WHERE id=? LIMIT 1'):$pdo->prepare('SELECT id,title FROM classes WHERE id=? AND teacher_id=? LIMIT 1'); $user['role']==='admin'?$q->execute([$cid]):$q->execute([$cid,$user['id']]); $class=$q->fetch(); if(!$class) throw new RuntimeException('دسترسی به این کلاس ندارید.');
   $q=$pdo->prepare('SELECT id,name,email,role FROM users WHERE id=? LIMIT 1'); $q->execute([$uid]); $target=$q->fetch(); if(!$target) throw new InvalidArgumentException('کاربر پیدا نشد.'); if($target['role']!=='student') throw new InvalidArgumentException('فقط می‌توان به حساب دانش‌آموز دسترسی کلاس داد.');
   $pdo->prepare("INSERT INTO class_allowed_users(class_id,user_id,email,created_at,updated_at) VALUES(?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE email=VALUES(email),updated_at=NOW()")->execute([$cid,$uid,$target['email']]);
   $success='دسترسی «'.($target['name']?:$target['email']).'» به «'.$class['title'].'» داده شد.'; $page='create_access';
  }
  if($action==='remove_allowed') {
   require_teacher(); if(!$hasAllowed) throw new RuntimeException('جدول کاربران مجاز ساخته نشده است.'); $aid=(int)($_POST['allowed_id']??0);
   $q=$user['role']==='admin'?$pdo->prepare('DELETE FROM class_allowed_users WHERE id=?'):$pdo->prepare('DELETE cau FROM class_allowed_users cau JOIN classes c ON c.id=cau.class_id WHERE cau.id=? AND c.teacher_id=?'); $user['role']==='admin'?$q->execute([$aid]):$q->execute([$aid,$user['id']]); $success='دسترسی کلاس حذف شد.'; $page='create_access';
  }
  if($action==='make_admin') {
   if(!admin_only($user)) throw new RuntimeException('فقط مدیر می‌تواند مدیر جدید اضافه کند.'); $email=strtolower(trim((string)($_POST['email']??''))); if(!filter_var($email,FILTER_VALIDATE_EMAIL)) throw new InvalidArgumentException('ایمیل معتبر نیست.');
   $q=$pdo->prepare('SELECT id FROM users WHERE email=? LIMIT 1'); $q->execute([$email]); $target=$q->fetch(); if(!$target) throw new InvalidArgumentException('کاربری با این ایمیل پیدا نشد.'); $pdo->prepare("UPDATE users SET role='admin',updated_at=NOW() WHERE id=?")->execute([(int)$target['id']]); $success='دسترسی مدیر داده شد.'; $page='admins';
  }
  if($action==='remove_admin') {
   if(!admin_only($user)) throw new RuntimeException('دسترسی ندارید.'); $id=(int)($_POST['user_id']??0); if($id===(int)$user['id']) throw new InvalidArgumentException('دسترسی مدیر خودت را نمی‌توانی حذف کنی.');
   $pdo->prepare("UPDATE users SET role='student',updated_at=NOW() WHERE id=? AND role='admin'")->execute([$id]); $success='دسترسی مدیر حذف شد.'; $page='admins';
  }
 }catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'عملیات انجام نشد.';}
}

$classes=[];$students=[];$admins=[];$allowedRows=[];$editClass=null;$ads=[];
if(manager($user)){
 if($user['role']==='admin')$classes=$pdo->query("SELECT c.*,u.name teacher_name FROM classes c JOIN users u ON u.id=c.teacher_id ORDER BY c.created_at DESC")->fetchAll(); else{$q=$pdo->prepare("SELECT c.*,u.name teacher_name FROM classes c JOIN users u ON u.id=c.teacher_id WHERE c.teacher_id=? ORDER BY c.created_at DESC");$q->execute([$user['id']]);$classes=$q->fetchAll();}
 $students=$pdo->query("SELECT id,name,email,created_at FROM users WHERE role='student' ORDER BY name")->fetchAll();
 if($hasAllowed){if($user['role']==='admin')$allowedRows=$pdo->query("SELECT cau.id,cau.class_id,cau.user_id,cau.email,c.title,c.room_code,u.name student_name FROM class_allowed_users cau JOIN classes c ON c.id=cau.class_id JOIN users u ON u.id=cau.user_id ORDER BY cau.id DESC")->fetchAll();else{$q=$pdo->prepare("SELECT cau.id,cau.class_id,cau.user_id,cau.email,c.title,c.room_code,u.name student_name FROM class_allowed_users cau JOIN classes c ON c.id=cau.class_id JOIN users u ON u.id=cau.user_id WHERE c.teacher_id=? ORDER BY cau.id DESC");$q->execute([$user['id']]);$allowedRows=$q->fetchAll();}}
 if(admin_only($user))$admins=$pdo->query("SELECT id,name,email,created_at FROM users WHERE role='admin' ORDER BY name")->fetchAll();
}
if($page==='classes'&&isset($_GET['edit'])){$cid=(int)$_GET['edit'];$q=$user['role']==='admin'?$pdo->prepare('SELECT * FROM classes WHERE id=?'):$pdo->prepare('SELECT * FROM classes WHERE id=? AND teacher_id=?');$user['role']==='admin'?$q->execute([$cid]):$q->execute([$cid,$user['id']]);$editClass=$q->fetch()?:null;}
try{$ads=$pdo->query("SELECT * FROM advertisements ORDER BY active DESC,id DESC")->fetchAll();}catch(Throwable $e){}
?>
<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پنل | کاداد کلاس</title><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link href="https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"><style>:root{--p:#635bff;--t:#101828;--m:#667085;--b:#e4e7ec;--bg:#f6f7fb;--s:#0b1020}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font-family:Vazirmatn,Tahoma,sans-serif}.app{min-height:100vh;display:flex}.side{width:250px;background:var(--s);color:#fff;padding:18px 13px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column}.brand{display:flex;gap:10px;align-items:center;color:#fff;text-decoration:none;font-weight:900;padding:8px 10px 22px}.logo{width:40px;height:40px;border-radius:12px;background:linear-gradient(135deg,#766cff,#5148e8);display:grid;place-items:center}.nav{display:flex;flex-direction:column;gap:4px}.nav a{color:#b9c2d3;text-decoration:none;padding:11px 12px;border-radius:10px;font-size:13px;font-weight:700}.nav a:hover,.nav a.active{background:#1a2340;color:#fff}.sep{height:1px;background:#27314a;margin:9px}.logout{margin-top:auto;color:#cbd5e1;background:#151d32;border-radius:10px;padding:10px;text-align:center;text-decoration:none;font-size:12px;font-weight:800}.main{flex:1;min-width:0;padding:28px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.top h1{margin:0;font-size:27px}.top p{margin:5px 0 0;color:var(--m);font-size:12px}.user{background:#fff;border:1px solid var(--b);padding:9px 12px;border-radius:11px;color:var(--m);font-size:12px}.card{background:#fff;border:1px solid var(--b);border-radius:17px;padding:19px;margin-bottom:16px;box-shadow:0 6px 22px rgba(16,24,40,.04)}.card h2{margin:0 0 15px;font-size:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:15px}.stat{font-size:30px;font-weight:900}.muted{color:var(--m);font-size:12px;line-height:1.9}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.full{grid-column:1/-1}label{display:block;font-size:12px;font-weight:800;margin-bottom:6px}input,textarea,select{width:100%;border:1px solid var(--b);border-radius:10px;padding:10px 12px;font:inherit;background:#fff}textarea{min-height:85px}.btn{display:inline-block;border:0;border-radius:10px;padding:10px 14px;background:var(--p);color:#fff;font:800 12px Vazirmatn;cursor:pointer;text-decoration:none}.secondary{background:#eef0ff;color:#4d45d8}.danger{background:#fff0f1;color:#be123c}.actions{display:flex;gap:7px;flex-wrap:wrap}.msg{padding:11px 13px;border-radius:11px;margin-bottom:14px;font-size:13px}.err{background:#fff1f2;color:#be123c}.ok{background:#ecfdf3;color:#027a48}.info{background:#eff6ff;color:#1d4ed8}.table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:right;padding:10px 8px;border-bottom:1px solid var(--b);white-space:nowrap}th{color:var(--m);font-size:11px}.code{display:inline-block;background:#f1f2ff;color:#5148e8;border-radius:8px;padding:5px 8px;font-weight:900;letter-spacing:2px}.pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#f2f4f7;color:#475467;font-size:10px;font-weight:800}.note{font-size:11px;color:var(--m);margin-top:7px}@media(max-width:700px){.app{display:block}.side{width:100%;height:auto;position:static}.nav{display:grid;grid-template-columns:1fr 1fr}.logout{margin-top:14px}.main{padding:15px}.fields{grid-template-columns:1fr}.full{grid-column:auto}.top{flex-direction:column;align-items:flex-start;gap:10px}}</style></head><body><div class="app"><aside class="side"><a class="brand" href="/panel"><span class="logo">ک</span><span>کاداد کلاس</span></a><nav class="nav"><a class="<?= $page==='dashboard'?'active':'' ?>" href="<?=url_page('dashboard')?>">🏠 داشبورد</a><?php if(manager($user)): ?><a class="<?= $page==='create_student'?'active':'' ?>" href="<?=url_page('create_student')?>">👨‍🎓 ساخت دانش‌آموز</a><a class="<?= $page==='students'?'active':'' ?>" href="<?=url_page('students')?>">👥 دانش‌آموزان</a><a class="<?= in_array($page,['classes','create_class'],true)?'active':'' ?>" href="<?=url_page('classes')?>">🏫 کلاس‌ها</a><a class="<?= $page==='create_class'?'active':'' ?>" href="<?=url_page('create_class')?>">➕ ساخت کلاس</a><a class="<?= $page==='create_access'?'active':'' ?>" href="<?=url_page('create_access')?>">🔐 ساخت درخواست دسترسی</a><a class="<?= $page==='ads'?'active':'' ?>" href="<?=url_page('ads')?>">📢 تبلیغات</a><?php if(admin_only($user)): ?><div class="sep"></div><a class="<?= $page==='admins'?'active':'' ?>" href="<?=url_page('admins')?>">👑 مدیران</a><?php endif; ?><?php endif; ?></nav><a class="logout" href="/login/logout.php">خروج از حساب</a></aside><main class="main"><div class="top"><div><h1><?php $titles=['dashboard'=>'داشبورد','create_student'=>'ساخت دانش‌آموز','students'=>'دانش‌آموزان','classes'=>'کلاس‌ها','create_class'=>'ساخت کلاس','create_access'=>'ساخت درخواست دسترسی','admins'=>'مدیران','ads'=>'تبلیغات'];echo h($titles[$page]??'پنل'); ?></h1><p><?=h($user['name'])?> · <?=h(role_label($user['role']))?></p></div><div class="user"><?=h($user['email'])?></div></div><?php if($error):?><div class="msg err"><?=h($error)?></div><?php endif;?><?php if($success):?><div class="msg ok"><?=h($success)?></div><?php endif;?>
<?php if($page==='dashboard'): ?><div class="grid"><div class="card"><div class="muted">کلاس‌ها</div><div class="stat"><?=count($classes)?></div></div><?php if(manager($user)): ?><div class="card"><div class="muted">دانش‌آموزان</div><div class="stat"><?=count($students)?></div></div><div class="card"><div class="muted">دسترسی‌های کلاس</div><div class="stat"><?=count($allowedRows)?></div></div><?php endif; ?></div><div class="card"><h2>شروع سریع ⚡</h2><div class="actions"><?php if(manager($user)): ?><a class="btn" href="<?=url_page('create_class')?>">ساخت کلاس</a><a class="btn secondary" href="<?=url_page('create_access')?>">دادن دسترسی به کاربر</a><?php else: ?><a class="btn" href="/join">ورود به کلاس</a><?php endif; ?></div></div>
<?php elseif($page==='create_student'): ?><div class="card"><h2>ساخت حساب دانش‌آموز</h2><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create_student"><div class="fields"><div><label>نام</label><input name="name" required></div><div><label>ایمیل</label><input name="email" type="email" required></div><div><label>رمز عبور</label><input name="password" type="password" minlength="8" required></div></div><button class="btn" style="margin-top:13px">ساخت دانش‌آموز</button></form></div>
<?php elseif($page==='students'): ?><div class="card"><div class="top" style="margin:0 0 8px"><h2>دانش‌آموزان</h2><a class="btn" href="<?=url_page('create_student')?>">+ ساخت</a></div><div class="table"><table><tr><th>نام</th><th>ایمیل</th><th>تاریخ</th></tr><?php foreach($students as $s): ?><tr><td><?=h($s['name'])?></td><td><?=h($s['email'])?></td><td><?=dt($s['created_at'])?></td></tr><?php endforeach;?><?php if(!$students): ?><tr><td colspan="3" class="muted">دانش‌آموزی وجود ندارد.</td></tr><?php endif;?></table></div></div>
<?php elseif($page==='create_access'): ?><div class="card"><h2>ساخت درخواست دسترسی 🔐</h2><p class="muted">کاربر و کلاس را انتخاب کن تا دسترسی ورود به آن کلاس برای کاربر ثبت شود. این دسترسی مستقیم است و کاربر بعد از ورود به حساب، بدون صف تأیید می‌تواند وارد کلاس شود.</p><?php if(!$hasAllowed): ?><div class="msg info">جدول کاربران مجاز ساخته نشده است. database/setup_access_controls.sql را اجرا کنید.</div><?php else: ?><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create_access"><div class="fields"><div><label>کاربر</label><select name="user_id" required><option value="">انتخاب دانش‌آموز</option><?php foreach($students as $s): ?><option value="<?=$s['id']?>"><?=h($s['name'])?> — <?=h($s['email'])?></option><?php endforeach;?></select></div><div><label>کلاس</label><select name="class_id" required><option value="">انتخاب کلاس</option><?php foreach($classes as $c): ?><option value="<?=$c['id']?>"><?=h($c['title'])?> — <?=h($c['room_code'])?></option><?php endforeach;?></select></div></div><button class="btn" style="margin-top:13px">دادن اجازه ورود</button></form><?php endif; ?></div><div class="card"><h2>دسترسی‌های ثبت‌شده</h2><?php if(!$allowedRows): ?><div class="muted">هنوز دسترسی‌ای ثبت نشده است.</div><?php else: ?><div class="table"><table><tr><th>کاربر</th><th>ایمیل</th><th>کلاس</th><th>کد</th><th>عملیات</th></tr><?php foreach($allowedRows as $a): ?><tr><td><?=h($a['student_name'])?></td><td><?=h($a['email'])?></td><td><?=h($a['title'])?></td><td><span class="code"><?=h($a['room_code'])?></span></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="remove_allowed"><input type="hidden" name="allowed_id" value="<?=$a['id']?>"><button class="btn danger">لغو دسترسی</button></form></td></tr><?php endforeach;?></table></div><?php endif; ?></div>
<?php elseif($page==='create_class'): ?><div class="card"><h2>ساخت کلاس 🎓</h2><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create_class"><div class="fields"><div><label>عنوان کلاس</label><input name="title" maxlength="200" required></div><?php if($hasStarts): ?><div><label>زمان شروع</label><input name="starts_at" type="datetime-local" required></div><?php endif; ?><div><label>مدت (دقیقه)</label><input name="duration" type="number" min="15" max="1440" value="60" required></div><div class="full"><label>توضیحات</label><textarea name="description"></textarea></div><?php if($hasGuest): ?><div class="full"><label><input type="checkbox" name="allow_guest" value="1" style="width:auto;margin-left:6px"> ورود بدون لاگین مجاز باشد</label><div class="note">اگر خاموش باشد، کاربر مهمان قبل از ورود به کلاس به صفحه ورود هدایت می‌شود.</div></div><?php endif; ?></div><button class="btn" style="margin-top:13px">ساخت کلاس</button></form></div>
